var mySize, angle;
var seed = Math.random() * 1000;
var color1, color2;
let colors1 = "e3d7a3-f5989d-ea618e-fce4d6-caac71".split("-").map((a) => "#" + a +"80");
let colors2 = "6cbbd4-5863b1-5282a1-fee8f7-c1f29b".split("-").map((a) => "#" + a +"80");
let colors3 = "1b1b1b-292929-f3f3f3-222222-ff0000".split("-").map((a) => "#" + a +"80");
let colors4 = "70c1b3-aaf0d3-50514f-ffe066-247ba0".split("-").map((a) => "#" + a +"80");
let colors5 = "3c1642-386375-086375-b2ff9e-1dd3b0".split("-").map((a) => "#" + a +"80");
let colorbg = "ffffff".split("-").map((a) => "#" + a);
let colorbg2 = "ffffff01".split("-").map((a) => "#" + a);
let filter;
var t,timer;

function setup() {
	randomSeed(seed);
	mySize = max(windowWidth, windowHeight);
	createCanvas(windowWidth, windowHeight);
	background(255);
	t = timer =0;
	rez = c = n = 0.01;
	color1 = random([colors1, colors2, colors3, colors4, colors5]);
	color2 = random([colors1, colors2, colors3, colors4, colors5]);
	// pixelDensity(5);
	xOff = 0;
	yOff = 0;
	angle = 0;
	filter = new makeFilter();	
}

function draw() {
	randomSeed(seed);
	// background(colorbg2);
	noFill();
	let plus = random(200, 20);
	for (let i = xOff; i < width - xOff; i += plus) {
		for (let j = yOff; j < height - yOff; j += plus) {
			for (let k = 0; k < 4; k++) {
				strokeWeight(random(0.1,0.25*k));
				strokeCap(SQUARE);
				var n = noise(i * rez+t, j * rez + t);
				if (n > 0.35) {
					stroke(random(color1));
				} else {
					stroke(random(color2));
				}
        let scale_r=0.5;
				if (n > 0.45) {
					push();
					translate(i, j);
					rotate(random([PI / 2, PI, -PI / 2, -PI]) + angle);
					line(0, 0, -plus*scale_r-k, plus*scale_r-k);
					line(0, 0, -plus*scale_r-k, -plus*scale_r-k);
					pop();
				} else {
					push();
					translate(i, j);
					rotate(random([PI / 2, PI, -PI / 2, -PI]) - angle);
					line(0, 0, plus*scale_r-k, plus*scale_r-k);
					line(0, 0, plus*scale_r-k, -plus*scale_r-k);
					pop();
				}
			}
		}
	}
	t += 0;
	if (angle < PI) angle += TAU / 360*0.5;
	else noLoop();
	// image(overAllTexture, 0, 0);
}

function makeFilter() {
	// noiseのフィルターをつくる
	colorMode(HSB, 360, 100, 100, 100);
	drawingContext.shadowColor = color(0, 0, 5, 95);
	overAllTexture = createGraphics(width, height);
	overAllTexture.loadPixels();
	for (let i = 0; i < width; i++) {
		for (let j = 0; j < height; j++) {
			overAllTexture.set(
				i,
				j,
				color(
					0,
					0,
					95,
					noise(i / 3, j / 3, (i * j) / 50) * random(5, 15)
				)
			);
		}
	}
	overAllTexture.updatePixels();
}

function keyPressed() {
	//noLoop();
	saveCanvas("from Line to Surface (Untitled_20220116)", "jpg");
}

